const replaceQuestionAnswerer = `-- name: ReplaceQuestionAnswerer :one
WITH removed AS (
    DELETE FROM question_answerer
    WHERE question_answerer.question_id = $1
      AND question_answerer.workspace_id = $2
      AND question_answerer.user_id = $3
    RETURNING question_answerer.question_id
), added AS (
    INSERT INTO question_answerer (question_id, workspace_id, user_id)
    SELECT removed.question_id, $2, $4
    FROM removed
    ON CONFLICT (question_id, user_id) DO NOTHING
    RETURNING question_answerer.user_id
)
SELECT count(*)::bigint AS removed_count FROM removed
`

type ReplaceQuestionAnswererParams struct {
	QuestionID  pgtype.UUID `json:"question_id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
	FromUserID  pgtype.UUID `json:"from_user_id"`
	ToUserID    pgtype.UUID `json:"to_user_id"`
}

// Reassign: the new answerer takes the old one's place. removed_count is 0
// when the old user was not an answerer, and nothing changes then.
func (q *Queries) ReplaceQuestionAnswerer(ctx context.Context, arg ReplaceQuestionAnswererParams) (int64, error) {
	row := q.db.QueryRow(ctx, replaceQuestionAnswerer,
		arg.QuestionID,
		arg.WorkspaceID,
		arg.FromUserID,
		arg.ToUserID,
	)
	var removed_count int64
	err := row.Scan(&removed_count)
	return removed_count, err
}

