const upsertQuestionAnswer = `-- name: UpsertQuestionAnswer :one
INSERT INTO question_answer (id, question_id, workspace_id, answerer_user_id, value, note)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (question_id, answerer_user_id) DO UPDATE SET
    value = EXCLUDED.value,
    note = EXCLUDED.note,
    updated_at = clock_timestamp()
WHERE question_answer.workspace_id = EXCLUDED.workspace_id
RETURNING id, question_id, workspace_id, answerer_user_id, value, note, created_at, updated_at, (xmax = 0) AS inserted
`

